import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.Arrays;

/**
 * Secure Java Application Example
 * Demonstrates proper use of PreparedStatements to prevent SQL Injection.
 */
public class SecureWebApp {
    public void processLogin(String username, int age) {
        // Using parameterized queries prevents user input from being interpreted as SQL code.
        String sql = "SELECT * FROM users WHERE name=? AND age=?";

        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;

        try {
            // Simulated connection setup
            conn = getDummyConnection();
            pstmt = conn.prepareStatement(sql);

            // Parameters are safely set separately from the query structure
            pstmt.setString(1, username);
            pstmt.setInt(2, age);

            rs = pstmt.executeQuery();

            // Process results here
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            // Proper resource cleanup
            if (rs != null) try { rs.close(); } catch (SQLException e) {}
            if (pstmt != null) try { pstmt.close(); } catch (SQLException e) {}
            if (conn != null) try { conn.close(); } catch (SQLException e) {}
        }
    }
